Literal.Value:
'{
  "padding": 0,
  "params": [
    {
      "name": "title",
      "value": "Sales"
    },
    {
      "name": "targetLabel",
      "value": "Target"
    },
    {
      "name": "bandBreaks",
      "value": [
        0.7,
        0.9
      ]
    },
    {
      "name": "scaleMax",
      "value": 1.2
    },
    {
      "name": "bandColors",
      "value": [
        "#C8C6C4",
        "#DCDAD8",
        "#EDEBE9"
      ]
    },
    {
      "name": "axisFormat",
      "value": ".0%"
    },
    {
      "name": "barColor",
      "expr": "pbiColor(0, -0.5)"
    },
    {
      "name": "colorBarByStatus",
      "value": false
    },
    {
      "name": "targetColor",
      "value": "#252423"
    },
    {
      "name": "valueFormat",
      "value": "auto"
    },
    {
      "name": "prefix",
      "value": "$"
    },
    {
      "name": "pctFormat",
      "value": "+.1%"
    },
    {
      "name": "noDataText",
      "value": "n/a"
    },
    {
      "name": "varianceUnit",
      "value": "auto"
    },
    {
      "name": "higherIsBetter",
      "value": true
    },
    {
      "name": "colorGood",
      "expr": "pbiColor(''good'')"
    },
    {
      "name": "colorBad",
      "expr": "pbiColor(''bad'')"
    },
    {
      "name": "colorNeutral",
      "expr": "pbiColor(''neutral'')"
    },
    {
      "name": "arrowUp",
      "value": "▲"
    },
    {
      "name": "arrowDown",
      "value": "▼"
    },
    {
      "name": "arrowFlat",
      "value": "►"
    },
    {
      "name": "cardColor",
      "value": "#FFFFFF"
    },
    {
      "name": "borderColor",
      "value": "#E1DFDD"
    },
    {
      "name": "borderWidth",
      "value": 1
    },
    {
      "name": "cardRadius",
      "value": 4
    },
    {
      "name": "valueColor",
      "expr": "pbiColor(0, -0.5)"
    },
    {
      "name": "labelColor",
      "value": "#605E5C"
    },
    {
      "name": "mutedColor",
      "value": "#A19F9D"
    },
    {
      "name": "stacked",
      "expr": "width < 2.4 * height"
    },
    {
      "name": "unit",
      "expr": "stacked ? clamp(min(width / 240, height / 160), 0.5, 3) : clamp(min(width / 300, height / 90), 0.5, 3)"
    },
    {
      "name": "pad",
      "expr": "14 * unit"
    },
    {
      "name": "top0",
      "expr": "max(0, (height - (stacked ? 160 : 90) * unit) / 2)"
    },
    {
      "name": "textLimit",
      "expr": "stacked ? width - 2 * pad : width * 0.44 - 1.5 * pad"
    },
    {
      "name": "titleSize",
      "expr": "(stacked ? 13 : 11.5) * unit"
    },
    {
      "name": "titleY",
      "expr": "top0 + (stacked ? 24 : 21) * unit"
    },
    {
      "name": "valueSize",
      "expr": "(stacked ? 36 : 26) * unit"
    },
    {
      "name": "valueY",
      "expr": "top0 + (stacked ? 66 : 52) * unit"
    },
    {
      "name": "gapSize",
      "expr": "(stacked ? 12.5 : 11) * unit"
    },
    {
      "name": "gapY",
      "expr": "top0 + (stacked ? 88 : 71) * unit"
    },
    {
      "name": "bulletX0",
      "expr": "stacked ? pad : width * 0.44"
    },
    {
      "name": "bulletX1",
      "expr": "width - pad"
    },
    {
      "name": "labelSize",
      "expr": "9.5 * unit"
    },
    {
      "name": "targetLabelY",
      "expr": "top0 + (stacked ? 106 : 22) * unit"
    },
    {
      "name": "bandY0",
      "expr": "top0 + (stacked ? 112 : 29) * unit"
    },
    {
      "name": "bandY1",
      "expr": "top0 + (stacked ? 136 : 61) * unit"
    },
    {
      "name": "barY0",
      "expr": "top0 + (stacked ? 119 : 39) * unit"
    },
    {
      "name": "barY1",
      "expr": "top0 + (stacked ? 129 : 51) * unit"
    },
    {
      "name": "tickY0",
      "expr": "top0 + (stacked ? 108 : 25) * unit"
    },
    {
      "name": "tickY1",
      "expr": "top0 + (stacked ? 140 : 65) * unit"
    },
    {
      "name": "axisY",
      "expr": "top0 + (stacked ? 153 : 78) * unit"
    }
  ],
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "Value",
          "as": "vSum"
        },
        {
          "op": "valid",
          "field": "Value",
          "as": "vN"
        },
        {
          "op": "sum",
          "field": "Target",
          "as": "tgSum"
        },
        {
          "op": "valid",
          "field": "Target",
          "as": "tgN"
        }
      ]
    },
    {
      "calculate": "datum.vN > 0 ? datum.vSum : null",
      "as": "v"
    },
    {
      "calculate": "datum.tgN > 0 ? datum.tgSum : null",
      "as": "tg"
    },
    {
      "calculate": "isValid(datum.v) && isValid(datum.tg) ? datum.v - datum.tg : null",
      "as": "d"
    },
    {
      "calculate": "isValid(datum.d) && datum.tg !== 0 ? datum.d / abs(datum.tg) : null",
      "as": "p"
    },
    {
      "calculate": "isValid(datum.v) && isValid(datum.tg) && datum.tg !== 0 ? datum.v / datum.tg : null",
      "as": "r"
    },
    {
      "calculate": "isValid(datum.d) ? (higherIsBetter ? 1 : -1) * datum.d : 0",
      "as": "g"
    },
    {
      "calculate": "(datum.g > 0 ? colorGood : datum.g < 0 ? colorBad : colorNeutral)",
      "as": "statusColor"
    },
    {
      "calculate": "(varianceUnit === ''points'' || (varianceUnit === ''auto'' && indexof(valueFormat, ''%'') >= 0))",
      "as": "isPts"
    },
    {
      "calculate": "(!isValid(datum.v) || !isFinite(datum.v) ? noDataText : valueFormat !== ''auto'' ? format(datum.v, valueFormat) : (datum.v < 0 ? ''−'' : '''') + prefix + format(abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1), abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.v) >= 999.5e6 ? ''bn'' : abs(datum.v) >= 999.5e3 ? ''M'' : abs(datum.v) >= 999.5 ? ''K'' : ''''))",
      "as": "valueText"
    },
    {
      "calculate": "(!isValid(datum.tg) || !isFinite(datum.tg) ? noDataText : valueFormat !== ''auto'' ? format(datum.tg, valueFormat) : (datum.tg < 0 ? ''−'' : '''') + prefix + format(abs(datum.tg) / (abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1), abs(datum.tg) / (abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.tg) >= 999.5e6 ? ''bn'' : abs(datum.tg) >= 999.5e3 ? ''M'' : abs(datum.tg) >= 999.5 ? ''K'' : ''''))",
      "as": "targetText"
    },
    {
      "calculate": "(!isValid(datum.d) ? '''' : datum.d > 0 ? arrowUp : datum.d < 0 ? arrowDown : arrowFlat) + '' '' + (datum.isPts ? (!isValid(datum.d) ? noDataText : (datum.d > 0 ? ''+'' : datum.d < 0 ? ''−'' : '''') + format(abs(datum.d) * 100, ''.1f'') + '' pts'') : (isValid(datum.d) && datum.d > 0 ? ''+'' : '''') + (!isValid(datum.d) || !isFinite(datum.d) ? noDataText : valueFormat !== ''auto'' ? format(datum.d, valueFormat) : (datum.d < 0 ? ''−'' : '''') + prefix + format(abs(datum.d) / (abs(datum.d) >= 999.5e6 ? 1e9 : abs(datum.d) >= 999.5e3 ? 1e6 : abs(datum.d) >= 999.5 ? 1e3 : 1), abs(datum.d) / (abs(datum.d) >= 999.5e6 ? 1e9 : abs(datum.d) >= 999.5e3 ? 1e6 : abs(datum.d) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.d) >= 999.5e6 ? 1e9 : abs(datum.d) >= 999.5e3 ? 1e6 : abs(datum.d) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.d) >= 999.5e6 ? ''bn'' : abs(datum.d) >= 999.5e3 ? ''M'' : abs(datum.d) >= 999.5 ? ''K'' : '''')) + '' ('' + (!isValid(datum.p) || !isFinite(datum.p) ? noDataText : format(datum.p, pctFormat)) + '')'')",
      "as": "gapText"
    },
    {
      "calculate": "max(scaleMax, 1.04, isValid(datum.r) ? datum.r * 1.04 : 0)",
      "as": "scaleEnd"
    },
    {
      "calculate": "bulletX0 + (clamp(isValid(datum.r) ? datum.r : 0, 0, datum.scaleEnd)) / datum.scaleEnd * (bulletX1 - bulletX0)",
      "as": "barEnd"
    },
    {
      "calculate": "bulletX0 + (1) / datum.scaleEnd * (bulletX1 - bulletX0)",
      "as": "targetX"
    },
    {
      "calculate": "targetLabel + '' '' + datum.targetText",
      "as": "targetLabelText"
    },
    {
      "calculate": "min(max(datum.targetX, bulletX0 + labelSize * 0.29 * length(datum.targetLabelText)), bulletX1 - labelSize * 0.29 * length(datum.targetLabelText))",
      "as": "targetLabelX"
    },
    {
      "calculate": "colorBarByStatus ? datum.statusColor : barColor",
      "as": "barFill"
    },
    {
      "calculate": "bulletX0",
      "as": "bx0"
    },
    {
      "calculate": "barY0",
      "as": "by0"
    },
    {
      "calculate": "barY1",
      "as": "by1"
    },
    {
      "calculate": "tickY0",
      "as": "ty0"
    },
    {
      "calculate": "tickY1",
      "as": "ty1"
    },
    {
      "calculate": "datum.gapText",
      "as": "tipGap"
    }
  ],
  "layer": [
    {
      "description": "Card background and border, inset by half the border so the container never clips it",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "rect",
        "x": {
          "expr": "borderWidth / 2"
        },
        "y": {
          "expr": "borderWidth / 2"
        },
        "x2": {
          "expr": "width - borderWidth / 2"
        },
        "y2": {
          "expr": "height - borderWidth / 2"
        },
        "fill": {
          "expr": "cardColor"
        },
        "stroke": {
          "expr": "borderColor"
        },
        "strokeWidth": {
          "expr": "borderWidth"
        },
        "cornerRadius": {
          "expr": "cardRadius"
        }
      }
    },
    {
      "description": "Title",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "pad"
        },
        "y": {
          "expr": "titleY"
        },
        "fontSize": {
          "expr": "titleSize"
        },
        "limit": {
          "expr": "textLimit"
        },
        "fill": {
          "expr": "labelColor"
        },
        "text": {
          "expr": "title"
        }
      }
    },
    {
      "description": "Value",
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": "bold",
        "x": {
          "expr": "pad"
        },
        "y": {
          "expr": "valueY"
        },
        "fontSize": {
          "expr": "valueSize"
        },
        "limit": {
          "expr": "textLimit"
        },
        "fill": {
          "expr": "valueColor"
        }
      },
      "encoding": {
        "text": {
          "field": "valueText",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Value"
          },
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          },
          {
            "field": "tipGap",
            "type": "nominal",
            "title": "Gap"
          }
        ]
      }
    },
    {
      "description": "Gap to target, coloured good or bad",
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "pad"
        },
        "y": {
          "expr": "gapY"
        },
        "fontSize": {
          "expr": "gapSize"
        },
        "limit": {
          "expr": "textLimit"
        }
      },
      "encoding": {
        "text": {
          "field": "gapText",
          "type": "nominal"
        },
        "color": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "description": "Qualitative bands, one row each from the breaks",
      "transform": [
        {
          "calculate": "sequence(0, length(bandBreaks) + 1)",
          "as": "bi"
        },
        {
          "flatten": [
            "bi"
          ]
        },
        {
          "calculate": "datum.bi === 0 ? 0 : bandBreaks[datum.bi - 1]",
          "as": "s0"
        },
        {
          "calculate": "min(datum.bi === length(bandBreaks) ? datum.scaleEnd : bandBreaks[datum.bi], datum.scaleEnd)",
          "as": "s1"
        },
        {
          "filter": "datum.s1 > datum.s0"
        },
        {
          "calculate": "bulletX0 + (datum.s0) / datum.scaleEnd * (bulletX1 - bulletX0)",
          "as": "x0"
        },
        {
          "calculate": "bulletX0 + (datum.s1) / datum.scaleEnd * (bulletX1 - bulletX0)",
          "as": "x1"
        },
        {
          "calculate": "bandY0",
          "as": "y0"
        },
        {
          "calculate": "bandY1",
          "as": "y1"
        },
        {
          "calculate": "bandColors[clamp(higherIsBetter ? datum.bi : length(bandBreaks) - datum.bi, 0, length(bandColors) - 1)]",
          "as": "fillBand"
        }
      ],
      "mark": {
        "type": "rect"
      },
      "encoding": {
        "x": {
          "field": "x0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "x1"
        },
        "y": {
          "field": "y0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "y1"
        },
        "color": {
          "field": "fillBand",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "description": "Value bar",
      "transform": [
        {
          "filter": "datum.barEnd > datum.bx0"
        }
      ],
      "mark": {
        "type": "rect"
      },
      "encoding": {
        "x": {
          "field": "bx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "barEnd"
        },
        "y": {
          "field": "by0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "by1"
        },
        "color": {
          "field": "barFill",
          "type": "nominal",
          "scale": null
        },
        "tooltip": [
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Value"
          },
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          },
          {
            "field": "tipGap",
            "type": "nominal",
            "title": "Gap"
          }
        ]
      }
    },
    {
      "description": "Target tick",
      "transform": [
        {
          "filter": "isValid(datum.r)"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": {
          "expr": "2.5 * unit"
        },
        "stroke": {
          "expr": "targetColor"
        },
        "strokeCap": "butt"
      },
      "encoding": {
        "x": {
          "field": "targetX",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "targetX"
        },
        "y": {
          "field": "ty0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "ty1"
        },
        "tooltip": [
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          }
        ]
      }
    },
    {
      "description": "Target label over the tick, kept inside the bullet",
      "transform": [
        {
          "filter": "isValid(datum.r)"
        }
      ],
      "mark": {
        "type": "text",
        "align": "center",
        "baseline": "alphabetic",
        "fontWeight": "normal",
        "y": {
          "expr": "targetLabelY"
        },
        "fontSize": {
          "expr": "labelSize"
        },
        "fill": {
          "expr": "labelColor"
        }
      },
      "encoding": {
        "x": {
          "field": "targetLabelX",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "targetLabelText",
          "type": "nominal"
        }
      }
    },
    {
      "description": "Band labels under the bullet, one per break; the target is labelled over its tick",
      "transform": [
        {
          "calculate": "sequence(0, length(bandBreaks))",
          "as": "li"
        },
        {
          "flatten": [
            "li"
          ]
        },
        {
          "calculate": "bandBreaks[datum.li]",
          "as": "ls"
        },
        {
          "filter": "datum.ls < datum.scaleEnd"
        },
        {
          "calculate": "bulletX0 + (datum.ls) / datum.scaleEnd * (bulletX1 - bulletX0)",
          "as": "lx"
        },
        {
          "calculate": "format(datum.ls, axisFormat)",
          "as": "lt"
        }
      ],
      "mark": {
        "type": "text",
        "align": "center",
        "baseline": "alphabetic",
        "fontWeight": "normal",
        "y": {
          "expr": "axisY"
        },
        "fontSize": {
          "expr": "labelSize"
        },
        "fill": {
          "expr": "mutedColor"
        }
      },
      "encoding": {
        "x": {
          "field": "lx",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "lt",
          "type": "nominal"
        }
      }
    }
  ]
}'
